import sys

def solve():
    data = sys.stdin.read().split()
    idx = 0
    if not data:
        return
    P = int(data[idx])
    idx += 1

    results = []

    for _ in range(P):
        N = int(data[idx])
        idx += 1
        row1 = data[idx]
        idx += 1
        row2 = data[idx]
        idx += 1

        if N == 1:
            if row1[0] == row2[0]:
                results.append(1)
            else:
                results.append(2)
            continue

        distinct_strings = set()

        def dfs(path, visited_mask, r, c, total_visited):
            if total_visited == 2 * N:
                distinct_strings.add(''.join(path))
                return

            if total_visited > 2 * N:
                return

            directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 2 and 0 <= nc < N:
                    bit = (nr << 9) | nc
                    if not (visited_mask & (1 << bit)):
                        new_mask = visited_mask | (1 << bit)
                        if nr == 0:
                            char = row1[nc]
                        else:
                            char = row2[nc]
                        path.append(char)
                        dfs(path, new_mask, nr, nc, total_visited + 1)
                        path.pop()

        for start_r in range(2):
            for start_c in range(N):
                bit = (start_r << 9) | start_c
                initial_mask = 1 << bit
                if start_r == 0:
                    start_char = row1[start_c]
                else:
                    start_char = row2[start_c]
                dfs([start_char], initial_mask, start_r, start_c, 1)

        results.append(len(distinct_strings))

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
